mapper.select:
select lautr.id, lautr.user_id, lautr.activity_id, lautr.task_item_id, lautr.create_user_id, lautr.update_user_id, lautr.create_time, lautr.update_time, usee.nickname, usee.avatar, acti.name as activityName, items.name as taskName from la_activity_user_task_record lautr join la_user usee on lautr.user_id = usee.id join la_activity acti on lautr.activity_id = acti.id join la_activity_task_item items on lautr.task_item_id = items.id
and lautr.is_delete = 0
and lautr.user_id = #{param.userId}
and lautr.activity_id = #{param.activityId}
and lautr.task_item_id = #{param.taskItemId}
and lautr.create_user_id = #{param.createUserId}
and lautr.update_user_id = #{param.updateUserId}
order by lautr.id desc

select lautr.id, lautr.user_id, lautr.activity_id, lautr.task_item_id, lautr.create_user_id, lautr.update_user_id, lautr.create_time, lautr.update_time, usee.nickname, usee.avatar, acti.name as activityName, items.name as taskName from la_activity_user_task_record lautr join la_user usee on lautr.user_id = usee.id join la_activity acti on lautr.activity_id = acti.id join la_activity_task_item items on lautr.task_item_id = items.id
and lautr.is_delete = 0
and lautr.id = #{id}
